"use strict";
function attempt(fn, retries) {
  function run(resolve, reject) {
    let n = 0;
    function bail(err) {
      reject(err || new Error("Aborted"));
    }
    function onError(err) {
      if (err.bail) {
        bail(err);
        return;
      }
      if (n > retries) reject(err);
      else runAttempt();
    }
    function runAttempt() {
      n++;
      let val;
      try {
        val = fn(bail, n);
      } catch (err) {
        onError(err);
        return;
      }
      Promise.resolve(val).then(resolve).catch(onError);
    }
    runAttempt();
  }
  return new Promise(run);
}
module.exports = { attempt };
